"""Verify packaged OCR/runtime using only images generated by this program."""
import ctypes
from datetime import datetime, timezone, timedelta
import json
import os
from pathlib import Path
import platform
import sys
import time

import numpy as np
from PIL import Image, ImageDraw, ImageFont

from .config import project_root
from .vision import Ocr, parse_number
from .windows import INPUT


def run_selftest():
    root=project_root()
    destination=root/'data'/'runtime-selftest.json'
    destination.parent.mkdir(parents=True,exist_ok=True)
    report={'time':datetime.now(timezone(timedelta(hours=8))).isoformat(),
            'scope':'本程序生成的测试图和运行库；没有读取或操作战网/炉石',
            'frozen':bool(getattr(sys,'frozen',False)), 'platform':platform.platform(),
            'python':sys.version, 'passed':False}
    started=time.monotonic()
    try:
        expected_size=40 if ctypes.sizeof(ctypes.c_void_p)==8 else 28
        assert ctypes.sizeof(INPUT)==expected_size,'INPUT structure ABI mismatch'
        fontpath=Path(os.environ.get('BGA_TEST_FONT',str(Path(os.environ.get('WINDIR',r'C:\Windows'))/'Fonts'/'msyh.ttc')))
        font=ImageFont.truetype(str(fontpath),46)
        image=Image.new('RGB',(700,180),'white');draw=ImageDraw.Draw(image)
        draw.text((25,15),'当前积分 6000',fill='black',font=font)
        draw.text((25,90),'第8名',fill='black',font=font)
        engine=Ocr()
        tokens=engine.tokens(np.asarray(image)[:,:,::-1].copy())
        recognized=[dict(text=t.text,score=t.score) for t in tokens]
        report['text_detection']=recognized
        assert any('6000' in t.text and t.score>=.85 for t in tokens),'rating inference failed'
        assert any(parse_number(t.text,'placement')==8 and t.score>=.85 for t in tokens),'placement inference failed'
        lines=[]
        for text,kind,value in [('6000','rating',6000),('8','placement',8),('8/10','gold',8)]:
            line=Image.new('RGB',(300,90),'white')
            ImageDraw.Draw(line).text((20,10),text,fill='black',font=font)
            result=engine.recognize_line(np.asarray(line)[:,:,::-1].copy())
            lines.append(dict(input=text,output=[dict(text=t.text,score=t.score) for t in result]))
            assert any(parse_number(t.text,kind)==value and t.score>=.85 for t in result),f'line inference failed: {kind}'
        report['numeric_lines']=lines
        report['passed']=True
    except Exception as error:
        import traceback
        report['error']=f'{type(error).__name__}: {error}'
        report['traceback']=traceback.format_exc()
    report['elapsed_seconds']=round(time.monotonic()-started,3)
    destination.write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
    return 0 if report['passed'] else 1
